import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"后记","description":"","frontmatter":{},"headers":[],"relativePath":"后记.md","filePath":"后记.md","lastUpdated":1792430298000}'),s={name:"后记.md"};function n(l,a,p,i,c,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="后记" tabindex="-1">后记 <a class="header-anchor" href="#后记" aria-label="Permalink to &quot;后记&quot;">​</a></h1><blockquote><p>写到这里，这份指南的第一版骨架就算立起来了。</p></blockquote><h2 id="想清楚的三件事" tabindex="-1">想清楚的三件事 <a class="header-anchor" href="#想清楚的三件事" aria-label="Permalink to &quot;想清楚的三件事&quot;">​</a></h2><p><strong>第一，指南是「地图」，不是「捷径」。</strong> 地图只告诉你哪里有路，路要自己走。每一个方向背后都是几百小时的练习——这正是它值得的原因。</p><p><strong>第二，网安人的三件套：好奇心、动手、守法。</strong> 好奇心驱动你深挖，动手让知识变成能力，守法让你走得更远而不是更快出事。</p><p><strong>第三，这是一份持续生长的文档。</strong> 第一版一定有不完善的地方：课程信息会变、资源链接会失效、新方向会出现。它需要一届又一届 FAFU 学子的接力维护，才配得上「指南」二字。</p><h2 id="给后来者的话" tabindex="-1">给后来者的话 <a class="header-anchor" href="#给后来者的话" aria-label="Permalink to &quot;给后来者的话&quot;">​</a></h2><p>如果你是大一新生：恭喜你，选了一个难但值得的专业。别怕基础差，这个专业最公平的地方在于——<strong>刷过的题、写过的 Writeup、打过的比赛，都不会骗你</strong>。</p><p>如果你是高年级同学：希望这份指南的「以赛促学」部分能帮你找到组织，把经验沉淀成页面，传给下一届。</p><p>如果你是社会上的安全从业者：欢迎通过 Issue 指正与补充，让母校的后来者看到行业真实的模样。</p><h2 id="开始吧" tabindex="-1">开始吧 <a class="header-anchor" href="#开始吧" aria-label="Permalink to &quot;开始吧&quot;">​</a></h2><p>第一站：<a href="/FAFU-Cybersecurity-Guide/前言.html">前言</a> → <a href="./课程地图.html">专业与课程地图</a>，然后打开你的第一台虚拟机。</p><blockquote><p>网络安全的第一原则，永远是<strong>合法合规</strong>。祝你在数字世界里，做一个正直而锋利的人。</p></blockquote>',13)])])}const u=t(s,[["render",n]]);export{_ as __pageData,u as default};
